<script setup>import AppLayout from '../../../Layouts/AppLayout.vue'; import PaginationLinks from '../../../components/ui/PaginationLinks.vue'; import ResourceToolbar from '../../../components/ui/ResourceToolbar.vue'; import {useResourceFilters} from '../../../composables/useResourceFilters'; const props=defineProps({entries:Object,filters:Object,endpoints:Object}); const {filters,clear}=useResourceFilters({search:props.filters.search||'',status:props.filters.status||''},props.endpoints.index);</script>
<template><AppLayout title="Asientos contables" eyebrow="Contabilidad" description="Borradores, contabilizaciones y reversiones trazables."><template #header-actions><a :href="endpoints.create" class="btn-primary">Nuevo asiento</a></template><ResourceToolbar v-model="filters.search" v-model:status="filters.status" :statuses="[{value:'draft',label:'Borrador'},{value:'posted',label:'Contabilizado'},{value:'reversed',label:'Reversado'}]" @clear="clear"/><section class="card mt-4 overflow-hidden"><div v-for="entry in entries.data" :key="entry.id" class="flex justify-between border-b p-4"><div><a :href="`/contabilidad/asientos/${entry.id}`" class="font-semibold text-blue-700">{{entry.number}}</a><p class="mt-1 text-xs">{{entry.concept}}</p><p class="text-[10px] text-slate-400">{{entry.date}} · {{entry.status}}</p></div><div class="text-right"><p class="font-semibold">C$ {{entry.total_debit}}</p><p class="text-[10px] text-slate-400">Debe / Haber</p></div></div><PaginationLinks :links="entries.links"/></section></AppLayout></template>
